use serde_json::{json, Value};
use std::io::Write;
use std::process::Command as Proc;

fn s(d: &str) -> Value { json!({"type":"string","description":d}) }
fn n(d: &str) -> Value { json!({"type":"number","description":d}) }
fn obj(props: Vec<(&str, Value)>, req: &[&str]) -> Value { let mut m = serde_json::Map::new(); for (k, v) in props { m.insert(k.into(), v); } json!({"type":"object","properties":m,"required":req}) }
fn sa<'a>(a: &'a Value, k: &str) -> Result<&'a str, String> { a.get(k).and_then(|v| v.as_str()).ok_or_else(|| crate::errors::arg_err(a, k, "string")) }
fn na(a: &Value, k: &str) -> Result<f64, String> { a.get(k).and_then(|v| v.as_f64()).ok_or_else(|| crate::errors::arg_err(a, k, "number")) }
fn on(a: &Value, k: &str, d: f64) -> f64 { a.get(k).and_then(|v| v.as_f64()).unwrap_or(d) }

/// Frame of one clip in isolation (its own effects included) at a timeline time.
fn clip_frame(p: &Project, clip_id: &str, t: f64) -> Result<Frame, String> {
    let mut q = p.clone(); let mut keep = None; for (ti, tr) in q.tracks.iter().enumerate() { if tr.clips.iter().any(|c| c.id == clip_id) { keep = Some(ti); } }
    let ti = keep.ok_or(format!("no clip '{clip_id}'"))?; let mut tr = q.tracks[ti].clone(); tr.clips.retain(|c| c.id == clip_id);
    let c = &mut tr.clips[0]; let local = t - c.start;
    if !local.is_finite() || local < -1e-7 || local >= c.duration { return Err("sample time must be inside clip".into()); }
    // Snap floating error from shifted frame boundaries, retaining the original
    // timeline clock for dynamic text/expressions and time-dependent source content.
    let frame = local.max(0.0) * q.fps;
    let snapped = if (frame-frame.round()).abs() < 1e-7 { c.start + frame.round()/q.fps + 1e-8/q.fps } else { t };
    q.tracks = vec![tr];
    let mut cache = render::Cache::new(); render::prepare_at(&q, &mut cache, Some(snapped))?; render::render_frame(&q, snapped, &cache)
}
pub(crate) fn any_frame(p: &Project, clip: Option<&str>, t: f64) -> Result<Frame, String> { match clip { Some(c) => clip_frame(p, c, t), None => { let mut cache = render::Cache::new(); render::prepare_at(p, &mut cache, Some(t))?; render::render_frame(p, t, &cache) } } }
fn stats(f: &Frame, region: Option<[f64; 4]>) -> Result<([f32; 3], [f32; 3]),String> {
    if let Some(r)=region{if r.iter().any(|v|!v.is_finite())||r[0]<0.||r[1]<0.||r[2]<=0.||r[3]<=0.||r[0]+r[2]>1.||r[1]+r[3]>1.{return Err("sample region must be positive and within0..1".into())}}
    let (x0, y0, x1, y1) = match region { Some(r) => ((r[0] * f.w as f64) as usize, (r[1] * f.h as f64) as usize, ((r[0] + r[2]) * f.w as f64) as usize, ((r[1] + r[3]) * f.h as f64) as usize), None => (0, 0, f.w, f.h) };
    let (mut s1, mut s2, mut c) = ([0f64; 3], [0f64; 3], 0f64); for y in y0..y1.min(f.h) { for x in x0..x1.min(f.w) { for j in 0..3 { let v = f.d[(y * f.w + x) * 4 + j].clamp(0.0, 1.0) as f64; s1[j] += v; s2[j] += v * v; } c += 1.0; } }
    if c==0.{return Err("sample region contains no pixels".into())}let m = [(s1[0] / c) as f32, (s1[1] / c) as f32, (s1[2] / c) as f32]; let sd = [0, 1, 2].map(|j| ((s2[j] / c - (s1[j] / c).powi(2)).max(0.0).sqrt()) as f32); Ok((m, sd)) }

fn add_fx(p: &mut Project, clip_id: &str, kind: &str, vals: &[(&str, f64)]) -> Result<String, String> {
    let id = p.gen_id("fx"); let c = p.find_clip_mut(clip_id).ok_or("no such clip")?; let mut params = std::collections::BTreeMap::new(); for (k, v) in vals { params.insert(k.to_string(), Prop::new(*v)); }
    c.effects.push(Effect { id: id.clone(), kind: kind.into(), params, strings: Default::default() }); Ok(id) }

fn scope_encoder_command(w:usize,h:usize,path:&str)->Proc{let mut cmd=Proc::new("ffmpeg");cmd.args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s",&format!("{w}x{h}"),"-i","-","-frames:v","1",path]);cmd}
fn high_bit_encoder_command(w:usize,h:usize,path:&str)->Proc{let mut cmd=Proc::new("ffmpeg");cmd.args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba64le","-s",&format!("{w}x{h}"),"-i","-","-frames:v","1","-pix_fmt","rgba64be",path]);cmd}
fn encode_still_bytes(cmd:&mut Proc,bytes:Vec<u8>,expected:usize,deadline:std::time::Duration)->Result<(),String>{if bytes.len()!=expected{return Err("still byte count mismatch".into())}let mut encoder=crate::color::process::EncodeStream::new(cmd,expected,deadline)?;encoder.write(bytes)?;encoder.finish()}

/// Render a scope to a PNG: waveform | parade | vectorscope | histogram.
pub fn scope_png(f: &Frame, kind: &str, path: &str) -> Result<(), String> {
    crate::guard::check();
    let pixels=f.w.checked_mul(f.h).filter(|n|*n>0).ok_or("invalid scope frame dimensions")?;if pixels.checked_mul(4)!=Some(f.d.len()){return Err("invalid scope frame shape".into())}
    let (ow, oh) = match kind { "vectorscope" => (320usize, 320usize), _ => (512, 288) };let out_bytes=ow.checked_mul(oh).and_then(|n|n.checked_mul(4)).ok_or("scope byte count overflow")?;let acc_bytes=ow.checked_mul(oh).and_then(|n|n.checked_mul(3*std::mem::size_of::<f32>())).ok_or("scope allocation overflow")?;crate::guard::reserve(acc_bytes.checked_add(out_bytes).and_then(|n|n.checked_add(if kind=="histogram"{ow*3*std::mem::size_of::<f32>()}else{0})).ok_or("scope allocation overflow")?);let mut acc = vec![0f32; ow * oh * 3];
    let lum = |c: [f32; 3]| 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
    let step = ((f.w * f.h) / 200_000).max(1);
    match kind {
        "waveform" | "parade" => { let parade = kind == "parade"; for y in (0..f.h).step_by(1) { if y%32==0{crate::guard::check()} for x in (0..f.w).step_by(step.min(f.w)) { let i = (y * f.w + x) * 4; let c = [f.d[i], f.d[i + 1], f.d[i + 2]];
            if parade { let third = ow / 3; for j in 0..3 { let ox = j * third + x * third / f.w; let oy = ((1.0 - c[j].clamp(0.0, 1.0)) * (oh - 1) as f32) as usize; acc[(oy * ow + ox) * 3 + j] += 1.0; } }
            else { let ox = x * ow / f.w; let l = lum(c).clamp(0.0, 1.0); let oy = ((1.0 - l) * (oh - 1) as f32) as usize; for j in 0..3 { acc[(oy * ow + ox) * 3 + j] += 1.0; } } } } }
        "vectorscope" => { for y in (0..f.h).step_by(1) { if y%32==0{crate::guard::check()} for x in (0..f.w).step_by(step.min(f.w)) { let i = (y * f.w + x) * 4; let (r, g, b) = (f.d[i].clamp(0.0, 1.0), f.d[i + 1].clamp(0.0, 1.0), f.d[i + 2].clamp(0.0, 1.0)); let yy = 0.2126 * r + 0.7152 * g + 0.0722 * b; let cb = (b - yy) / 1.8556; let cr = (r - yy) / 1.5748;
            let ox = ((cb * 1.0 + 0.5) * (ow - 1) as f32) as usize; let oy = ((0.5 - cr * 1.0) * (oh - 1) as f32) as usize; let k = (oy.min(oh - 1) * ow + ox.min(ow - 1)) * 3; acc[k] += r; acc[k + 1] += g; acc[k + 2] += b; } } }
        "histogram" => { let mut hist = vec![[0f32; 3]; ow]; for (sample,i) in (0..f.w * f.h).step_by(step).enumerate() { if sample%65536==0{crate::guard::check()} for j in 0..3 { let v = f.d[i * 4 + j].clamp(0.0, 1.0); hist[((v * (ow - 1) as f32) as usize).min(ow - 1)][j] += 1.0; } }
            let mx = hist.iter().flat_map(|h| h.iter()).cloned().fold(1.0, f32::max).sqrt(); for x in 0..ow { if x%32==0{crate::guard::check()} for j in 0..3 { let hh = ((hist[x][j].sqrt() / mx) * oh as f32) as usize; for y in oh.saturating_sub(hh)..oh { acc[(y * ow + x) * 3 + j] += 1.0; } } } }
        o => return Err(format!("unknown scope '{o}' (waveform|parade|vectorscope|histogram)")) }
    let mx = acc.iter().cloned().fold(1.0, f32::max); let gain = if kind == "histogram" { 0.55 } else { 14.0 / (mx.sqrt().max(1.0)) };
    let mut out = vec![0u8; out_bytes];
    for y in 0..oh { if y%32==0{crate::guard::check()} for x in 0..ow { let k = (y * ow + x) * 3; let o = (y * ow + x) * 4; let a = [acc[k], acc[k + 1], acc[k + 2]]; let mut c = if kind == "waveform" || kind == "vectorscope" { let m = (a[0] + a[1] + a[2]) / 3.0; let t = (m.max(0.0).sqrt() * gain / 4.0).min(1.0); if kind == "waveform" { [0.2 * t + 0.0, 1.0 * t, 0.35 * t] } else { let (mr, mgg, mb) = if m > 0.0 { (a[0] / m, a[1] / m, a[2] / m) } else { (0.0, 0.0, 0.0) }; [(mr * t).min(1.0) * 1.0, (mgg * t).min(1.0), (mb * t).min(1.0)] } } else { [(a[0].sqrt() * gain).min(1.0), (a[1].sqrt() * gain).min(1.0), (a[2].sqrt() * gain).min(1.0)] };
        if kind == "parade" || kind == "histogram" { let _ = &mut c; }
        // graticule
        let (gx, gy) = (x as f32 / ow as f32, y as f32 / oh as f32);
        if kind == "waveform" || kind == "parade" { for lv in [0.0, 0.1, 0.5, 0.9, 1.0] { if ((1.0 - gy) - lv).abs() < 0.0018 { for j in 0..3 { c[j] = c[j].max(0.22); } } } }
        if kind == "vectorscope" { let (dx, dy) = (gx - 0.5, gy - 0.5); let r = (dx * dx + dy * dy).sqrt(); for rr in [0.25, 0.5] { if (r - rr * 0.5 * 1.0).abs() < 0.002 { for j in 0..3 { c[j] = c[j].max(0.25); } } } let ang = (-dy).atan2(dx).to_degrees(); if ((ang - 123.0).abs() < 0.6 && r < 0.5) { c[0] = c[0].max(0.9); c[1] = c[1].max(0.6); c[2] = c[2].max(0.4); } if dx.abs() < 0.002 || dy.abs() < 0.002 { for j in 0..3 { c[j] = c[j].max(0.15); } } }
        for j in 0..3 { out[o + j] = (c[j].clamp(0.0, 1.0) * 255.0) as u8; } out[o + 3] = 255; } }
    encode_still_bytes(&mut scope_encoder_command(ow,oh,path),out,out_bytes,crate::color::process::encode_deadline(1)) }

